DOMAIN18 = [{'num': 18, 'topic': 18, 'title': 'Produce an evidence-led incident report', 'objective': 'LO5', 'desc': 'Begin with scope and a baseline, then focus with endpoints, filters, time and graphs.', 'build': 'Evidence CSV and packet findings', 'services': 'Wireshark, TShark, Python', 'steps': [('Prepare your lab workspace. Open this lab folder in a terminal. Windows uses py -3 in place of python3. Wireshark GUI alone is sufficient for the investigation; CLI scripts require TShark on PATH. Run the fixture verification first.', 'python3 scripts/verify.py'), ('Open data/branch-office.pcap. Read assets/incident-ticket.md. Use Statistics > Conversations, filters and Expert Information to identify the failing /fault request.', ''), ('Record evidence for the DNS delay, slow HTTP response, retransmission, zero window and port 81 refusal. Use exact frames and elapsed times rather than a claim that every symptom has one cause.', ''), ('Complete assets/report-template.md and save as outputs/incident-report.md. Include scope, timeline, observations, competing explanations, next capture placement and a client-safe recommendation.', ''), ('Use assets/ten-step-checklist.md to review the report. Re-run scripts/verify.py. Exchange reports with another learner and check that every conclusion can be traced to a packet or is explicitly a hypothesis.', ''), ('Export a reproducible packet table. Record the filter, frame numbers, measurement, explanation and limitation in outputs/findings.md.', 'python3 scripts/export_evidence.py')], 'test': 'The supplied http.response.code == 500 expression matches 1 frame(s) in the specified capture. Run scripts/verify.py and compare the listed frame numbers. Keep your findings and exported table in outputs/. Explain the observed result rather than only copying a count.', 'troubleshooting': 'TShark not found: install Wireshark CLI tools and add the installation folder to PATH; on Windows use the Wireshark install directory. A filter returns zero: clear other filters, use the specified capture, and check the expression is in the display toolbar. TLS remains opaque: select the matching lab-tls.keys file by absolute path, reload, and remove a key-log preference from another lab.', 'reflection': 'Which second observation point would strengthen your conclusion?', 'challenge': 'Develop and explain an alternative filter.', 'duration': 75}]
